import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';

// Admin Pages
import AdminCardRegister from './pages/admin/AdminCardRegister';

// User Pages
import UserLogin from './pages/user/UserLogin';
import UserRegister from './pages/user/UserRegister';
import UserDashboard from './pages/user/UserDashboard';

function App() {
  return (
    <>
      <Toaster position="top-right" reverseOrder={false} />
      <Router>
        <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 w-full">
          <Routes>
            {/* Default Landing Redirect */}
            <Route path="/" element={<Navigate to="/user/login" replace />} />

            {/* Public User Auth Routes */}
            <Route path="/user/login" element={<UserLogin />} />
            <Route path="/user/register" element={<UserRegister />} />

            {/* Protected User Portal */}
            <Route path="/user/dashboard" element={<UserDashboard />} />

            {/* Admin Management Portal */}
            <Route path="/admin/register" element={<AdminCardRegister />} />

            {/* Catch-all Fallback */}
            <Route path="*" element={<Navigate to="/user/login" replace />} />
          </Routes>
        </div>
      </Router>
    </>
  );
}

export default App;
